-- GENERATED by benchmarks/tpch/scripts/qualify_queries.py from ../queries — do not edit.
-- Mixed layout: dimensions in postgresql.tpch_mixed, facts in hive.tpch.
-- TPC-H Q22: Global Sales Opportunity — standard form
SELECT
    cntrycode,
    COUNT(*) AS numcust,
    SUM(c_acctbal) AS totacctbal
FROM (
    SELECT
        SUBSTRING(c_phone FROM 1 FOR 2) AS cntrycode,
        c_acctbal
    FROM postgresql.tpch_mixed.customer
    WHERE SUBSTRING(c_phone FROM 1 FOR 2) IN
            ('13', '31', '23', '29', '30', '18', '17')
        AND c_acctbal > (
            SELECT AVG(c_acctbal)
            FROM postgresql.tpch_mixed.customer
            WHERE c_acctbal > 0.00
                AND SUBSTRING(c_phone FROM 1 FOR 2) IN
                    ('13', '31', '23', '29', '30', '18', '17')
        )
        AND NOT EXISTS (
            SELECT *
            FROM hive.tpch.orders
            WHERE o_custkey = c_custkey
        )
) AS custsale
GROUP BY cntrycode
ORDER BY cntrycode
